 1| import { randomUUID } from 'node:crypto';
 2| import { paginate } from '../../lib/pagination.ts';
 3| import type { CreateProject, ListProjectsQuery, Project, ProjectPage, UpdateProject } from './schema.ts';
 4| 
 5| /** In-memory project store, ordered by creation time (ties broken by id). */
 6| const projects = new Map<string, Project>();
 7| 
 8| const sortKey = (project: Project): string => `${project.createdAt}|${project.id}`;
 9| 
10| export function listProjects(query: ListProjectsQuery): ProjectPage {
11|   const matching = query.status === undefined
12|     ? [...projects.values()]
13|     : [...projects.values()].filter((project) => project.status === query.status);
14|   return paginate(matching, query, sortKey);
15| }
16| 
17| export function deleteProject(id: string): boolean {
18|   return projects.delete(id);
19| }
20| 
21| export function getProject(id: string): Project | undefined {
22|   return projects.get(id);
23| }
24| 
25| export function createProject(input: CreateProject): Project {
26|   const now = new Date().toISOString();
27|   const project: Project = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
28|   projects.set(project.id, project);
29|   return project;
30| }
31| 
32| export function updateProject(id: string, patch: UpdateProject): Project | undefined {
33|   const current = projects.get(id);
34|   if (current === undefined) return undefined;
35|   const updated: Project = { ...current, ...patch, updatedAt: new Date().toISOString() };
36|   projects.set(id, updated);
37|   return updated;
38| }

